('cog6-dunya#19','cografiya','cog-6-dunya',3,4,'Şimal Buzlu okeanının xüsusiyyəti nədir?','Ən soyuq və ən kiçik okeandır.',array['Ən soyuq və kiçik okeandır','Ən isti okeandır','Ən dərin okeandır','Şirin suludur'],1),
